Future<void> cleanupOldBackups() async {
try {
final List<BackupFileInfo> backups = await listBackups();

if (backups.length > maxBackupFiles) {
backups.sort(
(BackupFileInfo a, BackupFileInfo b) =>
b.createdAt.compareTo(a.createdAt),
);

final List<BackupFileInfo> filesToDelete = backups.sublist(
maxBackupFiles,
);

for (final BackupFileInfo backup in filesToDelete) {
await deleteFile(backup.name);
}
}
} catch (e, stackTrace) {
handleError(e, stackTrace, context: 'Error cleaning old backups');
throw Exception('Failed to cleanup old backups: $e');
}
}

Future<void> deleteFile(String fileName) async {
final drive.DriveApi? driveApi = await _getDriveApi();
if (driveApi == null) {
throw Exception('Failed to authenticate with Google Drive');
}
final drive.FileList files = await driveApi.files.list(
q: "name = '$fileName' and (mimeType = 'application/json')",
);
if (files.files == null || files.files!.isEmpty) {
throw Exception('Backup file not found');
}
final drive.File backupFile = files.files!.first;
return driveApi.files.delete(backupFile.id!);
}

Future<File> restoreFromGoogleDrive(String backupFileName) async {
final drive.DriveApi? driveApi = await _getDriveApi();
if (driveApi == null) {
throw Exception('Failed to authenticate with Google Drive');
}

final drive.FileList files = await driveApi.files.list(
q: "name = '$backupFileName' and (mimeType = 'application/json')",
);

if (files.files == null || files.files!.isEmpty) {
throw Exception('Backup file not found');
}

final drive.File backupFile = files.files!.first;
final drive.Media content =
await driveApi.files.get(
backupFile.id!,
downloadOptions: drive.DownloadOptions.fullMedia,
)
as drive.Media;

final Directory directory = await getApplicationDocumentsDirectory();
final File file = File('${directory.path}/$backupFileName');

List<int> dataStore = <int>[];
await for (List<int> data in content.stream) {
dataStore.addAll(data);
}
await file.writeAsBytes(dataStore);
return file;
}

Future<drive.File?> backupToGoogleDrive(
File file,
String backupFileName,
) async {
try {
final drive.DriveApi? driveApi = await _getDriveApi();
if (driveApi == null) {
throw Exception('Failed to authenticate with Google Drive');
}

await _ensureBackupFolder(driveApi);

// Get file length safely
final int fileLength = await file.length();
if (fileLength == 0) {
throw Exception('Backup file is empty');
}

final drive.Media media = drive.Media(file.openRead(), fileLength);

final drive.File driveFile = drive.File()
..name = backupFileName
..mimeType = 'application/json'
..parents = <String>[_backupFolderId!]
..appProperties = <String, String?>{
'appName': 'Paisa',
'version': await _getAppVersion(),
'createdAt': DateTime.now().toIso8601String(),
};
final drive.File uploadedFile = await driveApi.files.create(
driveFile,
uploadMedia: media,
);

await cleanupOldBackups();
return uploadedFile;
} catch (e, stackTrace) {
handleError(e, stackTrace, context: 'Error backing up to Google Drive');
return null;
}
}

Future<List<BackupFileInfo>> listBackups() async {
final drive.DriveApi? driveApi = await _getDriveApi();
if (driveApi == null) {
throw Exception('Failed to authenticate with Google Drive');
}

await _ensureBackupFolder(driveApi);

final drive.FileList files = await driveApi.files.list(
q: "(mimeType='application/json') and '$_backupFolderId' in parents",
orderBy: 'createdTime desc',
$fields: 'files(id,name,createdTime,size)',
);

return files.files
?.map(
(drive.File file) => BackupFileInfo(
id: file.id ?? '',
name: file.name ?? '',
createdAt: file.createdTime ?? DateTime.now(),
size: int.tryParse(file.size ?? '0') ?? 0,
),
)
.toList() ??
<BackupFileInfo>[];
}

Future<void> _createBackupFolder(drive.DriveApi driveApi) async {
final drive.File folder = drive.File()
..name = 'PaisaBackups'
..mimeType = 'application/vnd.google-apps.folder';

final drive.File response = await driveApi.files.create(folder);
_backupFolderId = response.id;
}

Future<drive.DriveApi?> _getDriveApi() async {
await _ensureInitialized();

try {
final GoogleSignInAccount? googleUser = await _attemptSilentSignIn();
if (googleUser == null) {
// User is not authenticated, prompt for login
return await _promptUserLogin();
}

_currentUser = googleUser;
// In v7.0+, authentication is synchronous (no await needed)
final GoogleSignInAuthentication googleAuth = googleUser.authentication;

final GoogleAuthClient authClient = GoogleAuthClient(googleAuth);
return drive.DriveApi(authClient);
} catch (error, stackTrace) {
handleError(error, stackTrace, context: 'Error getting Drive API');
log('Error getting Drive API: $error');
return null;
}
}

/// Attempts to sign in silently without user interaction
/// Uses attemptLightweightAuthentication() from v7.0+
Future<GoogleSignInAccount?> _attemptSilentSignIn() async {
await _ensureInitialized();

try {
// In v7.0+, attemptLightweightAuthentication replaces signInSilently
final Future<GoogleSignInAccount?>? result = _googleSignIn
.attemptLightweightAuthentication();

// Handle both sync and async returns
final GoogleSignInAccount? account;
if (result is Future<GoogleSignInAccount?>) {
account = await result;
} else {
account = result as GoogleSignInAccount?;
}

if (account != null) {
_currentUser = account;
log('Silent sign-in successful');
} else {
log('Silent sign-in returned null');
}

return account;
} catch (error, stackTrace) {
handleError(error, stackTrace, context: 'Silent sign-in failed');
log('Silent sign-in failed: $error');
return null;
}
}

Future<drive.DriveApi?> _promptUserLogin() async {
await _ensureInitialized();

try {
// In v7.0+, authenticate() replaces signIn()
final GoogleSignInAccount googleUser = await _googleSignIn.authenticate(
scopeHint: _scopes,
);

_currentUser = googleUser;
log('User sign-in successful');

// In v7.0+, authentication is synchronous (no await needed)
final GoogleSignInAuthentication googleAuth = googleUser.authentication;

// Create the auth client and return the Drive API
final GoogleAuthClient authClient = GoogleAuthClient(googleAuth);
return drive.DriveApi(authClient);
} on GoogleSignInException catch (e) {
// Handle specific Google Sign-In exceptions in v7.0+
final String errorMessage = _googleSignInExceptionToMessage(e);
handleError(
e,
StackTrace.current,
context: 'Login failed: ${e.code.name} - $errorMessage',
);
log('Login failed: ${e.code.name} - ${e.description}');
return null;
} catch (error, stackTrace) {
handleError(error, stackTrace, context: 'Login failed');
log('Login failed: $error');
return null;
}
}

/// Convert GoogleSignInException to user-friendly message
String _googleSignInExceptionToMessage(GoogleSignInException exception) {
switch (exception.code.name) {
case 'canceled':
return 'Sign-in was cancelled. Please try again.';
case 'interrupted':
return 'Sign-in was interrupted. Please try again.';
case 'clientConfigurationError':
return 'Google Sign-In configuration error. Please contact support.';
case 'providerConfigurationError':
return 'Google Sign-In is currently unavailable. Please try again later.';
case 'uiUnavailable':
return 'Google Sign-In UI is unavailable. Please try again later.';
case 'userMismatch':
return 'Account mismatch. Please sign out and try again.';
case 'unknownError':
default:
return 'An unexpected error occurred. Please try again.';
}
}

Future<void> _ensureBackupFolder(drive.DriveApi driveApi) async {
if (_backupFolderId != null) return;

const String query =
"mimeType='application/vnd.google-apps.folder' and name='PaisaBackups'";
final drive.FileList result = await driveApi.files.list(q: query);

if (result.files?.isEmpty ?? true) {
await _createBackupFolder(driveApi);
} else {
_backupFolderId = result.files!.first.id;
}
}

Future<String> _getAppVersion() async {
final PackageInfo packageInfo = await PackageInfo.fromPlatform();
return packageInfo.version;
}
}

class GoogleAuthClient extends http.BaseClient {
GoogleAuthClient(GoogleSignInAuthentication auth)
: _headers = <String, String>{
// In v7.0+, use serverAuthCode or idToken based on your needs
// For Drive API, we need the access token which is available in idToken
if (auth.idToken != null) 'Authorization': 'Bearer ${auth.idToken}',
};

@override
Future<http.StreamedResponse> send(http.BaseRequest request) {
request.headers.addAll(_headers);
return _client.send(request);
}

final http.Client _client = http.Client();
final Map<String, String> _headers;

@override
void close() {
_client.close();
}
}

class BackupFileInfo {
BackupFileInfo({
required this.id,
required this.name,
required this.createdAt,
required this.size,
});

final DateTime createdAt;
final String id;
final String name;
final int size;

String get formattedSize {
if (size < 1024) return '$size B';
if (size < 1024 * 1024) return '${(size / 1024).toStringAsFixed(1)} KB';
return '${(size / (1024 * 1024)).toStringAsFixed(1)} MB';
}

String get formattedDate =>
DateFormat('MMM dd, yyyy HH:mm').format(createdAt);
}

