firestore rules:

rules_version = '2';
service cloud.firestore {
match /databases/{database}/documents {

/* ----------------------------------------------------
✅ REQUIRED: collectionGroup(products) READ ACCESS
(THIS FIXES BEST DEALS & RESTOCK BUFFERING)
---------------------------------------------------- */
match /{path=**}/products/{productId} {
allow read: if true;
}

// Orders collection
match /orders/{orderId} {
allow read: if request.auth != null && (
resource.data.vendorId == request.auth.uid ||
resource.data.assignedToDelivery == request.auth.uid ||
resource.data.customerId == request.auth.uid
);
allow write: if request.auth != null && (
resource.data.customerId == request.auth.uid ||
resource.data.vendorId == request.auth.uid ||
resource.data.assignedToDelivery == request.auth.uid
);
}

// Delivery executives
match /deliveryExecutives/{userId} {
allow read, update, delete: if request.auth != null && request.auth.uid == userId;
allow create: if request.auth != null;

// ✅ Delivery Executive Reviews subcollection
match /reviews/{reviewId} {
allow read, update: if request.auth != null && request.auth.uid == userId; // delivery exec can view/update own reviews
allow create: if request.auth != null; // any logged-in user can leave a review
}
}

// Users (customers/vendors)
match /users/{userId} {
allow read, update, delete: if request.auth != null && request.auth.uid == userId;
allow create: if request.auth != null;

// ✅ explicit rule for user cart subcollection
match /cart/{cartId} {
allow read, write: if request.auth != null && request.auth.uid == userId;
}
}

// Vendors
match /vendors/{vendorId} {
allow read: if request.auth != null;
allow update, delete: if request.auth.uid == vendorId;
allow create: if request.auth != null;
}

// ✅ Customers collection
match /customers/{uid} {
allow read, write: if request.auth != null && request.auth.uid == uid;
}

// ✅ Products subcollection
match /vendors/{vendorId}/products/{productId} {
allow read: if true;
allow write: if request.auth != null && request.auth.uid == vendorId;
}

// ✅ Coupons subcollection
match /vendors/{vendorId}/coupons/{couponId} {
allow read, write: if request.auth != null && request.auth.uid == vendorId;
}

// ✅ Reviews subcollection
match /vendors/{vendorId}/reviews/{reviewId} {
allow read, update: if request.auth != null && request.auth.uid == vendorId;
allow create: if request.auth != null;
}

// ✅ Refunds subcollection
match /vendors/{vendorId}/refunds/{refundId} {
allow read, write: if request.auth != null && request.auth.uid == vendorId;
}

// ✅ Top-level categories collection (read-only)
match /categories/{categoryId} {
allow read: if true; // public read access
}
// ---------------- Shows / Seats (Movies & Events) ----------------
match /vendors/{vendorId}/shows/{showId} {
allow read: if true; // anyone can view shows
allow write: if request.auth != null && request.auth.uid == vendorId; // only vendor can create/update
}

match /vendors/{vendorId}/shows/{showId}/seats/{seatId} {
allow read: if true; // customers need to see seats
allow write: if request.auth != null && (
request.auth.uid == vendorId ||
request.auth.uid == request.resource.data.bookedBy // customer can only book for themselves
);
}
}
}

firebase storage rules:

rules_version = '2';

service firebase.storage {
match /b/{bucket}/o {

// Match for all files related to profile images uploads (for delivery executives)
match /profile_images/{userId}/{fileName} {
allow read: if request.auth != null && request.auth.uid == userId; // Only the user who uploaded the file can read it
allow write: if request.auth != null && request.auth.uid == userId; // Only the authenticated user can upload their identity file
}

// Match for all files related to identity uploads (for delivery executives)
match /identity_files/{userId}/{fileName} {
allow read: if request.auth != null && request.auth.uid == userId; // Only the user who uploaded the file can read it
allow write: if request.auth != null && request.auth.uid == userId; // Only the authenticated user can upload their identity file
}

// Match for all files related to product images (for vendors)
match /product_images/{vendorId}/{productId}/{fileName} {
allow read: if true;
allow write: if request.auth != null && request.auth.uid == vendorId; // Only the authenticated vendor can upload/update their product images
}

// Match for vendor images (for vendors)
match /vendor_images/{vendorId}/{fileName} {
allow read: if true;
allow write: if request.auth != null && request.auth.uid == vendorId; // Only the authenticated vendor can upload vendor images
}

// ---------------- Show / Event Posters ----------------
match /show_posters/{vendorId}/{showId}/{fileName} {
allow read: if true; // public posters
allow write: if request.auth != null && request.auth.uid == vendorId;
}

// General catch-all rule for any other file in the storage
match /{allPaths=**} {
allow read: if true;
allow write: if request.auth != null;
}
}
}

